\copy (select sigungu_code, bjdong_code, lot_type, bun, ji, max(raw_record->>'platPlc') plat, max(nullif(raw_record->>'newPlatPlc','')) road, count(*) filter (where energy_type='GAS' and usage_kwh is not null) gas_months, count(*) filter (where energy_type='ELECTRICITY' and source<>'K-apt' and usage_kwh is not null) elec_hub_months, count(*) filter (where source='K-apt') elec_kapt_months from energy_monthly group by 1,2,3,4,5) to stdout with csv header
